            if rf.issues or rf.warnings:
                print(f" [{len(rf.issues)} issues, {len(rf.warnings)} warnings]", end="")
            print()
            for issue in rf.issues:
                print(f"        [!] {issue}")
            for w in rf.warnings:
                print(f"        [~] {w}")
        print()
    else:
