    # Cross-file duplicates section
    if report.cross_file_duplicates:
        print("-" * 60)
        print(f"  CROSS-FILE DUPLICATES ({len(report.cross_file_duplicates)} found):")
        for line_text, file_list in report.cross_file_duplicates[:10]:
            print(f"    [!] \"{line_text}...\"")
